+            )),
+            Some(a) if a.iter().all(|c| c.is_finite()) && a[2] > 0.0175 => Ok([a[0] / a[2], a[1] / a[2]]),
+            Some(_) => Err(format!("move {n} states a pose the wire cannot hold (it leans past 89 degrees or is not a direction)")),
